findings.remediation:
Replace the 8 static blocks with a local map and a dynamic block, e.g.:

locals {
  db_flags = {
    log_lock_waits          = "on"
    log_disconnections      = "on"
    log_connections         = "on"
    log_checkpoints         = "on"
    log_duration            = "on"
    log_hostname            = "on"
    log_statement           = "ddl"
    "cloudsql.enable_pgaudit" = "on"
  }
}

# inside settings {}
dynamic "database_flags" {
  for_each = local.db_flags
  content {
    name  = database_flags.key
    value = database_flags.value
  }
}

